<?php require_once 'app.php';require_login();$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=(string)($_POST['atual']??'');$n=(string)($_POST['nova']??'');$s=db()->prepare('SELECT senha FROM usuarios WHERE id=?');$s->execute([user()['id']]);$u=$s->fetch();if(!$u||!password_verify($a,$u['senha'])||strlen($n)<8)$err='Senha atual inválida ou nova senha muito curta.';else{$s=db()->prepare('UPDATE usuarios SET senha=? WHERE id=?');$s->execute([password_hash($n,PASSWORD_DEFAULT),user()['id']]);flash('success','Senha alterada.');redirect('dashboard.php');}}layout_start('Alterar senha');?><div class="card p-4" style="max-width:600px"><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><label class="form-label">Senha atual</label><input type="password" name="atual" class="form-control mb-3" required><label class="form-label">Nova senha</label><input type="password" name="nova" minlength="8" class="form-control mb-3" required><button class="btn btn-primary">Salvar</button></form></div><?php layout_end();